const items = $input.all();
const checkedAt = new Date().toISOString();
const seenTowers = new Set();

function isMissing(value) {
  return value === null ||
    value === undefined ||
    (typeof value === "string" && value.trim() === "");
}

function checkNumber(row, field, errors, options = {}) {
  const value = row[field];

  if (isMissing(value)) {
    errors.push(`${field}: missing value`);
    return null;
  }

  const number = (
    typeof value === "number" ||
    typeof value === "string"
  ) ? Number(value) : NaN;

  if (!Number.isFinite(number)) {
    errors.push(`${field}: must be a valid number`);
    return null;
  }

  if (options.min !== undefined && number < options.min) {
    errors.push(`${field}: below minimum ${options.min}`);
  }

  if (options.max !== undefined && number > options.max) {
    errors.push(`${field}: above maximum ${options.max}`);
  }

  if (options.integer && !Number.isInteger(number)) {
    errors.push(`${field}: must be an integer`);
  }

  return number;
}

return items.map((item) => {
  const row = item.json;
  const errors = [];
  const warnings = [];

  const requiredFields = [
    "tower_id",
    "operator",
    "state",
    "city",
    "network_type",
    "data_origin",
    "risk_category_final",
    "predicted_risk_category"
  ];

  for (const field of requiredFields) {
    if (isMissing(row[field])) {
      errors.push(`${field}: missing value`);
    }
  }

  const towerId = String(row.tower_id ?? "")
    .trim()
    .toUpperCase();

  if (towerId) {
    if (seenTowers.has(towerId)) {
      warnings.push(
        "Duplicate tower_id within this batch"
      );
    }
    seenTowers.add(towerId);
  }

  checkNumber(row, "id", errors, {
    min: 1,
    integer: true
  });

  const uptime = checkNumber(
    row, "latest_uptime", errors,
    { min: 0, max: 100 }
  );

  checkNumber(
    row, "historical_total_downtime_minutes",
    errors, { min: 0 }
  );

  checkNumber(
    row, "historical_total_outage_count",
    errors, { min: 0, integer: true }
  );

  checkNumber(
    row, "site_reliability_risk_score",
    errors, { min: 0 }
  );

  const probability = checkNumber(
    row, "predicted_risk_probability",
    errors, { min: 0, max: 1 }
  );

  checkNumber(
    row, "recommended_priority",
    errors, { min: 1, integer: true }
  );

  if (uptime !== null && uptime < 90) {
    warnings.push(
      "Low uptime: requires operational review"
    );
  }

  if (probability !== null && probability >= 0.7) {
    warnings.push(
      "Elevated predicted risk probability"
    );
  }


const knownCityStates = {
  "kano": ["kano"],
  "abuja": ["fct", "federal capital territory"],
  "benin city": ["edo"],
  "abeokuta": ["ogun"],
  "ibadan": ["oyo"],
  "calabar": ["cross river"],
  "jos": ["plateau"]
};

  const city = String(row.city ?? "").trim().toLowerCase();
const state = String(row.state ?? "").trim().toLowerCase();




if (
  city &&
  !Object.prototype.hasOwnProperty.call(knownCityStates, city)
) {
  errors.push(
    `GEOGRAPHY_UNVERIFIED: ${row.city} requires reference verification`
  );
}

if (
  knownCityStates[city] &&
  !knownCityStates[city].includes(state)
) {
  errors.push(
    `GEOGRAPHIC_MISMATCH: ${row.city} does not belong to ${row.state}`
  );
}

  const isValid = errors.length === 0;

  return {
    json: {
      ...row,
      validation_status: isValid
        ? "PASSED_VALIDATION"
        : "FAILED_VALIDATION",
      is_valid: isValid,
      validation_errors: errors,
      validation_warnings: warnings,
      validation_error_count: errors.length,
      requires_review:
        errors.length > 0 || warnings.length > 0,
      validated_at: checkedAt
    }
  };
});

const items = $input.all();

// Configurable operational risk thresholds
const T = {
  criticalUptime: 90,
  highUptime: 97,
  watchUptime: 99,
  criticalProbability: 0.80,
  highProbability: 0.60,
  watchProbability: 0.40,
  highOutages: 20,
  watchOutages: 10,
  highDowntime: 500,
  watchDowntime: 240
};

function toNumber(value) {
  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ""
  ) return null;

  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

return items.filter(item => item.json.is_valid === true).map(item => {
  const r = item.json;

  const uptime = toNumber(r.latest_uptime);
  const outages = toNumber(
    r.historical_total_outage_count
  );
  const downtime = toNumber(
    r.historical_total_downtime_minutes
  );
  const probability = toNumber(
    r.predicted_risk_probability
  );

  const signals = [];
  const warnings = [];

  // Validate metric ranges
  if (uptime === null || uptime < 0 || uptime > 100) {
    warnings.push("Invalid or missing uptime");
  }
  if (outages === null || outages < 0) {
    warnings.push("Invalid or missing outage count");
  }
  if (downtime === null || downtime < 0) {
    warnings.push("Invalid or missing downtime");
  }
  if (
    probability === null ||
    probability < 0 ||
    probability > 1
  ) {
    warnings.push("Invalid or missing probability");
  }

  const u = uptime >= 0 && uptime <= 100
    ? uptime : null;
  const o = outages >= 0 ? outages : null;
  const d = downtime >= 0 ? downtime : null;
  const p = probability >= 0 && probability <= 1
    ? probability : null;

  // Interpret historical network performance
  if (u !== null && u < T.watchUptime) {
    signals.push("Reduced historical uptime");
  }
  if (o !== null && o >= T.watchOutages) {
    signals.push("Elevated historical outage count");
  }
  if (d !== null && d >= T.watchDowntime) {
    signals.push("Elevated historical downtime");
  }
  if (p !== null && p >= T.watchProbability) {
    signals.push("Elevated model risk probability");
  }

  // Transparent operational triage rules
  let riskLevel = "LOW";

  if (
    u === null &&
    o === null &&
    d === null &&
    p === null
  ) {
    riskLevel = "INSUFFICIENT_DATA";
  } else if (
    (u !== null && u < T.criticalUptime) ||
    (
      p !== null &&
      p >= T.criticalProbability &&
      o !== null &&
      o >= T.highOutages
    )
  ) {
    riskLevel = "CRITICAL";
  } else if (
    (u !== null && u < T.highUptime) ||
    (p !== null && p >= T.highProbability) ||
    (o !== null && o >= T.highOutages) ||
    (d !== null && d >= T.highDowntime)
  ) {
    riskLevel = "HIGH";
  } else if (
    (u !== null && u < T.watchUptime) ||
    (p !== null && p >= T.watchProbability) ||
    (o !== null && o >= T.watchOutages) ||
    (d !== null && d >= T.watchDowntime)
  ) {
    riskLevel = "MEDIUM";
  }

  const actionMap = {
    CRITICAL: "Urgent engineer review",
    HIGH: "Priority network inspection",
    MEDIUM: "Schedule preventive inspection",
    LOW: "Routine monitoring",
    INSUFFICIENT_DATA: "Verify performance metrics"
  };

  const qualityStatus = r.is_valid === false
    ? "REQUIRES_DATA_QUALITY_REVIEW"
    : r.is_valid === true
      ? "PASSED_CONFIGURED_CHECKS"
      : "NOT_VALIDATED";

  return {
    json: {
      ...r,
      operational_risk_level: riskLevel,
      recommended_action: actionMap[riskLevel],
      operational_risk_signals: signals,
      metric_warnings: warnings,
      data_quality_status: qualityStatus,
      active_outage_status: "NOT_VERIFIED",
      assessment_type: "HISTORICAL_AND_PREDICTIVE_TRIAGE",
      assessed_at: new Date().toISOString()
    }
  };
});

const towers = $input.all().map(item => item.json);

const critical = towers.filter(t =>
  t.operational_risk_level === "CRITICAL"
);

const high = towers.filter(t =>
  t.operational_risk_level === "HIGH"
);

const qualityReview = towers.filter(t =>
  t.data_quality_status ===
  "REQUIRES_DATA_QUALITY_REVIEW"
);

const priority = { CRITICAL: 0, HIGH: 1 };

const sorted = [...towers].sort((a, b) =>
  (priority[a.operational_risk_level] ?? 9) -
  (priority[b.operational_risk_level] ?? 9)
);

const lines = sorted.map((t, i) =>
  `${i + 1}. Tower: ${t.tower_id}
Operator: ${t.operator}
Risk Level: ${t.operational_risk_level}
Uptime: ${t.latest_uptime}%
Risk Probability: ${t.predicted_risk_probability}
Action: ${t.recommended_action}
Data Quality: ${t.data_quality_status}`
);


const alertSignature = JSON.stringify(
  [...towers]
    .sort((a, b) =>
      String(a.tower_id).localeCompare(String(b.tower_id))
    )
    .map(t => ({
      tower_id: t.tower_id,
      risk_level: t.operational_risk_level,
      probability: Number(
        t.predicted_risk_probability ?? 0
      ).toFixed(4),
      quality: t.data_quality_status,
      outage_status: t.active_outage_status
    }))
);


const report =
`TELECOM NETWORK RISK REVIEW
================================

Assessment Type: Historical & Predictive
Confirmed Live Outages: NOT VERIFIED

Towers Requiring Review: ${towers.length}
Critical Risk: ${critical.length}
High Risk: ${high.length}
Data Quality Review Required: ${qualityReview.length}

PRIORITY TOWER WATCHLIST
================================

${lines.join("\n\n")}

RECOMMENDED RESPONSE
================================
1. Verify flagged geographic data.
2. Review critical-risk towers first.
3. Investigate historical outage patterns.
4. Schedule preventive maintenance.
5. Confirm current network status using live telemetry.

Generated: ${new Date().toISOString()}
`;

return [{
  json: {
    alert_key: "TELECOM_RISK_REVIEW",
    alert_signature: alertSignature,
    alert_type: "RISK_REVIEW_REQUIRED",
    total_priority_towers: towers.length,
    critical_count: critical.length,
    high_count: high.length,
    quality_review_count: qualityReview.length,
    alert_subject: "Telecom Network Risk Review",
    alert_message: report,
    generated_at: new Date().toISOString()
  }
}];

const items = $input.all();

// Reference locations for the synthetic telecom dataset
const cityStateMap = {
  "kano": "Kano",
  "abuja": "FCT",
  "abeokuta": "Ogun",
  "ibadan": "Oyo",
  "benin city": "Edo",
  "calabar": "Cross River",
  "jos": "Plateau"
};

function normalize(value) {
  return String(value ?? "")
    .trim()
    .replace(/\s+/g, " ")
    .toLowerCase();
}

return items.map(item => {
  const row = { ...item.json };

  const city = normalize(row.city);
  const originalState = row.state ?? null;
  const currentState = normalize(originalState);

  const expectedState = cityStateMap[city];

  let status = "REFERENCE_REVIEW_REQUIRED";
  let corrected = false;

  if (expectedState) {
    const allowedStates = city === "abuja"
      ? ["fct", "federal capital territory"]
      : [normalize(expectedState)];

    if (!allowedStates.includes(currentState)) {
      row.state = expectedState;
      corrected = true;
      status = "CORRECTED_ASSUMED_FROM_CITY";
    } else {
      status = "ALREADY_CONSISTENT";
    }
  }

  return {
    json: {
      ...row,
      original_state: originalState,
      geography_corrected: corrected,
      geography_normalization_status: status,
      geography_reference: "SYNTHETIC_CITY_STATE_MAP",
      geography_checked_at: new Date().toISOString()
    }
  };
});

const source = $("Get row(s)").all().map(i => i.json);
const completed = $input.all().map(i => i.json);

if (!source.length || source.length !== completed.length) {
  throw new Error("Batch incomplete: checkpoint blocked");
}

function towerCounts(rows) {
  const counts = new Map();
  for (const row of rows) {
    const key = String(row.tower_id ?? "").trim();
    if (!key) throw new Error("Missing tower_id");
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  return counts;
}

const expected = towerCounts(source);
const actual = towerCounts(completed);

for (const [tower, count] of expected) {
  if (actual.get(tower) !== count) {
    throw new Error(`Missing or mismatched tower: ${tower}`);
  }
}

const ids = source.map(r => Number(r.id));

if (ids.some(id => !Number.isSafeInteger(id) || id <= 0)) {
  throw new Error("Invalid source row ID");
}

return [{
  json: {
    batch_key: "TELECOM_NETWORK",
    last_processed_id: Math.max(...ids),
    processed_count: completed.length,
    checkpoint_status: "READY_FOR_REVIEW"
  }
}];
